47	func (s *APIV1Service) GetInstanceStats(ctx context.Context, _ *v1pb.GetInstanceStatsRequest) (*v1pb.InstanceStats, error) {
48		user, err := s.fetchCurrentUser(ctx)
49		if err != nil {
